    order: { eyebrow: 'Bestellung', title: 'Stellen Sie Ihre Bestellung zusammen', lead: 'Beschreiben Sie, was Sie sich wünschen: das Stück, die Lederfarbe, die Größe, eine Gravur oder etwas ganz Eigenes. Ich antworte direkt hier auf der Website. Wenn Sie wiederkommen, sehen Sie unser Gespräch oben auf der Seite.', name: 'Name', email: 'E-Mail (optional)', details: 'Ihre Bestellung', placeholder: 'Zum Beispiel: Ich hätte gern die Maxi Bag mit kürzerem Riemen und dunklerem Leder…', send: 'Bestellung senden', sending: 'Wird gesendet…', ok: 'Danke! Ihre Bestellung ist eingegangen. Meine Antwort sehen Sie oben auf dieser Seite, kommen Sie einfach wieder auf die Website.', error: 'Senden fehlgeschlagen. Bitte versuchen Sie es erneut.', errName: 'Bitte geben Sie Ihren Namen ein.', errEmail: 'Bitte geben Sie eine gültige E-Mail-Adresse ein oder lassen Sie das Feld leer.', errDetails: 'Bitte beschreiben Sie Ihre Bestellung.', emailHint: 'Optional. Wir können das Gespräch hier auf der Website fortsetzen.' },
    conversation: { title: 'Ihr Gespräch mit SLOU', lead: 'Meine Antworten erscheinen hier. Kommen Sie jederzeit auf diese Seite zurück, das Gespräch ist in diesem Browser gespeichert.', you: 'Sie', shop: 'SLOU', waiting: 'Ich antworte so schnell wie möglich, schauen Sie später wieder vorbei.', placeholder: 'Nachricht schreiben…', send: 'Senden', sending: 'Wird gesendet…', error: 'Senden fehlgeschlagen. Bitte versuchen Sie es erneut.', empty: 'Bitte schreiben Sie eine Nachricht.', delete: 'Gespräch löschen', deleteConfirm: 'Dieses Gespräch löschen? Es verschwindet von dieser Seite.', deleteError: 'Löschen fehlgeschlagen. Bitte versuchen Sie es erneut.' },
    xmas: { eyebrow: 'Weihnachtsangebot', title: 'Weihnachtsgeschenke mit persönlicher Note', lead: 'Jedes Stück lässt sich personalisieren: Wir prägen Buchstaben, einen Namen, ein Wort oder ein Datum ins Leder.', wallet: 'Card wallet', walletDesc: 'Ein schlankes Kartenetui aus pflanzlich gegerbtem Leder.', keys: 'Schlüsselanhänger', keysDesc: 'Lederanhänger mit Namen, Wort oder Datum. Ein Geschenk für Familie, Kollegen oder Gäste.', bulk: 'Ab 10 Stück', each: '/ Stück', engrave: 'Mit geprägten Buchstaben', cta: 'Bestellen', prefill: 'Weihnachtsangebot: {name}\nMenge: \nPrägung: ', photos: 'Weitere Fotos', close: 'Schließen', expand: 'Vergrößern', was: 'Vorher', now: 'Jetzt' },
