    xmas: { eyebrow: 'Oferta de Navidad', title: 'Regalos de Navidad con un toque personal', lead: 'Todas las piezas se pueden personalizar: grabamos letras, un nombre, una palabra o una fecha en el cuero.', wallet: 'Card wallet', walletDesc: 'Una cartera fina para tarjetas en cuero de curtido vegetal.', keys: 'Llaveros', keysDesc: 'Llaveros de cuero con un nombre, una palabra o una fecha. Un regalo para la familia, compañeros o invitados.', bulk: 'Desde 10 uds.', each: '/ ud.', engrave: 'Con letras grabadas', cta: 'Pedir', prefill: 'Oferta de Navidad: {name}\nCantidad: \nGrabado: ', photos: 'Más fotos', close: 'Cerrar', expand: 'Ampliar', was: 'Antes', now: 'Ahora' },
